# --- Backend endpoint to generate pianoroll URL ---
@app.get("/api/get-pianoroll-url")
def get_pianoroll_url(track: int):
    """Return URL for the specific track’s pianoroll page."""
    return {"url": f"/pianoroll?track={track}"}



